CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_usuarios_empresa`  AS SELECT `u`.`id_usuario` AS `id_usuario`, `u`.`nombre_usuario` AS `nombre_usuario`, `u`.`rol` AS `rol`, `u`.`id_empresa` AS `id_empresa`, `e`.`nombre` AS `empresa_nombre`, `u`.`email` AS `email`, `u`.`can_view_inventory_history` AS `can_view_inventory_history`, `u`.`can_view_ticket_history` AS `can_view_ticket_history`, `u`.`can_manage_users` AS `can_manage_users` FROM (`usuarios` `u` left join `empresas` `e` on(`u`.`id_empresa` = `e`.`id_empresa`)) ;

